exercise.referenceSolution:
#include <algorithm>
#include <concepts>
#include <iostream>
#include <numbers>
#include <print>
#include <string>

template <typename T>
concept Shape = requires(const T &s) {
    { s.area() } -> std::convertible_to<double>;
    { s.name() } -> std::convertible_to<std::string>;
};

struct Rect {
    double w, h;
    double area() const {
        return w * h;
    }
    std::string name() const {
        return "прямоугольник";
    }
};

struct Circle {
    double r;
    double area() const {
        return std::numbers::pi * r * r;
    }
    std::string name() const {
        return "круг";
    }
};

struct Square {
    double a;
    double area() const {
        return a * a;
    }
    std::string name() const {
        return "квадрат";
    }
};

static_assert(Shape<Rect> && Shape<Circle> && Shape<Square>);
static_assert(!Shape<int>);

template <Shape S>
double report(const S &s) {
    const double a = s.area();
    std::println("{}: {:.2f}", s.name(), a);
    return a;
}

int main() {
    std::string kind;
    int count = 0;
    double best = 0;
    while (std::cin >> kind) {
        double a = 0;
        if (kind == "rect") {
            double w, h;
            std::cin >> w >> h;
            a = report(Rect{w, h});
        } else if (kind == "circle") {
            double r;
            std::cin >> r;
            a = report(Circle{r});
        } else {
            double side;
            std::cin >> side;
            a = report(Square{side});
        }
        best = count == 0 ? a : std::max(best, a);
        count++;
    }
    if (count == 0) {
        std::println("фигур нет");
    } else {
        std::println("всего {}, наибольшая площадь {:.2f}", count, best);
    }
    return 0;
}

